package com.example.cbflight;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point for the CBFLIGHT Spring Boot application.
 *
 * <p>Migrated from COBOL program CBFLIGHT (FLIGHT-DUPLICATE-COB).
 * The application exposes REST endpoints that replicate the original
 * batch logic: for each of the eight flight numbers defined in the
 * COBOL table, it fetches the seed flight record and duplicates it
 * for every day of September (month index 9 → 30 days).
 */
@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

