package com.example.cbflight.model;

import jakarta.persistence.*;
import java.time.LocalDate;
import java.time.LocalTime;

/**
 * JPA entity mapped to the {@code FLIGHT} table.
 *
 * <p>Field names and types mirror the original COBOL DCLFLIGHT copybook:
 * <ul>
 *   <li>FLIGHTID    – surrogate PK (S9(9) COMP)</li>
 *   <li>FLIGHTDATE  – date (PIC X format YYYY-MM-DD)</li>
 *   <li>DEPTIME     – departure time PIC X(8)</li>
 *   <li>ARRTIME     – arrival time   PIC X(8)</li>
 *   <li>TOTPASS     – total passengers S9(9) COMP</li>
 *   <li>TOTBAGGA    – total baggage   S9(9) COMP</li>
 *   <li>FLIGHTNUM   – flight number   PIC X(6)</li>
 *   <li>SHIFTID     – shift id        S9(9) COMP</li>
 *   <li>AIRPLANEID  – airplane id     PIC X(8)</li>
 *   <li>AIRPORTDEP  – departure airport PIC X(4)</li>
 *   <li>AIRPORTARR  – arrival airport   PIC X(4)</li>
 * </ul>
 */
@Entity
@Table(name = "FLIGHT")
public class Flight {

    /** Surrogate primary key – auto-generated by the database sequence. */
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE,
                    generator = "flight_seq")
    @SequenceGenerator(name = "flight_seq",
                       sequenceName = "flight_flightid_seq",
                       allocationSize = 1)
    @Column(name = "FLIGHTID")
    private Long flightId;

    /** Flight date. Maps to the COBOL WS-FLIGHTDATE composite field. */
    @Column(name = "FLIGHTDATE", nullable = false)
    private LocalDate flightDate;

    /** Scheduled departure time (HH:MM:SS). */
    @Column(name = "DEPTIME", length = 8)
    private String depTime;

    /** Scheduled arrival time (HH:MM:SS). */
    @Column(name = "ARRTIME", length = 8)
    private String arrTime;

    /** Total number of passengers. */
    @Column(name = "TOTPASS")
    private Integer totPass;

    /** Total baggage count. */
    @Column(name = "TOTBAGGA")
    private Integer totBagga;

    /** Six-character flight number (e.g. CB1104). */
    @Column(name = "FLIGHTNUM", length = 6, nullable = false)
    private String flightNum;

    /** Shift identifier. */
    @Column(name = "SHIFTID")
    private Integer shiftId;

    /** Airplane identifier code. */
    @Column(name = "AIRPLANEID", length = 8)
    private String airplaneId;

    /** IATA code of the departure airport. */
    @Column(name = "AIRPORTDEP", length = 4)
    private String airportDep;

    /** IATA code of the arrival airport. */
    @Column(name = "AIRPORTARR", length = 4)
    private String airportArr;

    // ── Constructors ────────────────────────────────────────────────

    /** Default no-arg constructor required by JPA. */
    public Flight() {}

    /**
     * Full constructor used when creating duplicated flight rows.
     *
     * @param flightDate  the date of the new flight
     * @param depTime     departure time string
     * @param arrTime     arrival time string
     * @param totPass     total passengers
     * @param totBagga    total baggage
     * @param flightNum   flight number code
     * @param shiftId     shift identifier
     * @param airplaneId  airplane identifier
     * @param airportDep  IATA departure airport
     * @param airportArr  IATA arrival airport
     */
    public Flight(LocalDate flightDate,
                  String depTime,
                  String arrTime,
                  Integer totPass,
                  Integer totBagga,
                  String flightNum,
                  Integer shiftId,
                  String airplaneId,
                  String airportDep,
                  String airportArr) {
        this.flightDate = flightDate;
        this.depTime    = depTime;
        this.arrTime    = arrTime;
        this.totPass    = totPass;
        this.totBagga   = totBagga;
        this.flightNum  = flightNum;
        this.shiftId    = shiftId;
        this.airplaneId = airplaneId;
        this.airportDep = airportDep;
        this.airportArr = airportArr;
    }

    // ── Getters & Setters ────────────────────────────────────────────

    public Long getFlightId()              { return flightId; }
    public void setFlightId(Long id)       { this.flightId = id; }

    public LocalDate getFlightDate()               { return flightDate; }
    public void setFlightDate(LocalDate flightDate){ this.flightDate = flightDate; }

    public String getDepTime()             { return depTime; }
    public void setDepTime(String depTime) { this.depTime = depTime; }

    public String getArrTime()             { return arrTime; }
    public void setArrTime(String arrTime) { this.arrTime = arrTime; }

    public Integer getTotPass()               { return totPass; }
    public void setTotPass(Integer totPass)   { this.totPass = totPass; }

    public Integer getTotBagga()               { return totBagga; }
    public void setTotBagga(Integer totBagga) { this.totBagga = totBagga; }

    public String getFlightNum()               { return flightNum; }
    public void setFlightNum(String flightNum) { this.flightNum = flightNum; }

    public Integer getShiftId()               { return shiftId; }
    public void setShiftId(Integer shiftId)   { this.shiftId = shiftId; }

    public String getAirplaneId()                { return airplaneId; }
    public void setAirplaneId(String airplaneId) { this.airplaneId = airplaneId; }

    public String getAirportDep()                { return airportDep; }
    public void setAirportDep(String airportDep) { this.airportDep = airportDep; }

    public String getAirportArr()                { return airportArr; }
    public void setAirportArr(String airportArr) { this.airportArr = airportArr; }

    @Override
    public String toString() {
        return "Flight{flightId=%d, flightNum='%s', flightDate=%s}"
               .formatted(flightId, flightNum, flightDate);
    }
}

