package com.example.cbflight.repository;

import com.example.cbflight.model.Flight;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * Spring Data JPA repository for the {@link Flight} entity.
 *
 * <p>The main query mirrors the COBOL paragraph {@code 0100-GET-DB2-DATA}:
 * <pre>
 *   SELECT * FROM FLIGHT WHERE FLIGHTNUM = :WS-FLIGHTNUM-DEF
 * </pre>
 * Because the COBOL program expects a single row (SELECT INTO), the method
 * returns {@link Optional}&lt;{@link Flight}&gt; and the service picks the
 * first result when multiple rows exist (seed record behaviour).
 */
@Repository
public interface FlightRepository extends JpaRepository<Flight, Long> {

    /**
     * Retrieves the first flight record matching the given flight number.
     *
     * <p>Equivalent to the COBOL SQL:
     * <pre>SELECT * FROM FLIGHT WHERE FLIGHTNUM = :WS-FLIGHTNUM-DEF</pre>
     *
     * @param flightNum the six-character flight number (e.g. "CB1104")
     * @return an {@link Optional} containing the seed flight, or empty if none found
     */
    @Query(value = "SELECT f FROM Flight f WHERE f.flightNum = :flightNum ORDER BY f.flightDate ASC")
    Optional<Flight> findFirstByFlightNum(@Param("flightNum") String flightNum);
}

