package com.example.cbflight.dto;

import java.util.List;

/**
 * Response DTO returned by the duplicate-flight endpoint.
 *
 * <p>Carries a summary of how many records were inserted per flight number,
 * together with any error messages encountered (mirroring the COBOL DISPLAY
 * statements on non-zero SQLCODEs).
 *
 * @param flightNum       the processed flight number
 * @param seedFlightId    the primary key of the seed (source) record
 * @param insertedCount   number of new rows successfully inserted
 * @param errors          list of error descriptions (empty on full success)
 */
public record DuplicateResultDto(
        String flightNum,
        Long   seedFlightId,
        int    insertedCount,
        List<String> errors
) {}

