package com.example.cbflight.controller;

import com.example.cbflight.dto.DuplicateBatchResultDto;
import com.example.cbflight.dto.DuplicateResultDto;
import com.example.cbflight.dto.SingleDuplicateRequestDto;
import com.example.cbflight.service.FlightDuplicateService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

/**
 * REST controller exposing the CBFLIGHT duplicate-flight functionality.
 *
 * <table border="1">
 *   <caption>Endpoints</caption>
 *   <tr><th>Method</th><th>Path</th><th>Description</th></tr>
 *   <tr>
 *     <td>POST</td>
 *     <td>/api/flights/duplicate/batch</td>
 *     <td>Runs the full COBOL batch (all 8 flight numbers)</td>
 *   </tr>
 *   <tr>
 *     <td>POST</td>
 *     <td>/api/flights/duplicate/single</td>
 *     <td>Duplicates a single, caller-supplied flight number</td>
 *   </tr>
 * </table>
 */
@RestController
@RequestMapping("/api/flights")
public class FlightDuplicateController {

    private final FlightDuplicateService flightDuplicateService;

    public FlightDuplicateController(FlightDuplicateService flightDuplicateService) {
        this.flightDuplicateService = flightDuplicateService;
    }

    /**
     * Triggers the full COBOL batch execution for all eight pre-defined
     * flight numbers (mirroring the outer {@code PERFORM VARYING COUNT2}
     * loop in the COBOL PROCEDURE DIVISION).
     *
     * @return {@code 200 OK} with a {@link DuplicateBatchResultDto} summary
     */
    @PostMapping("/duplicate/batch")
    public ResponseEntity<DuplicateBatchResultDto> runFullBatch() {
        DuplicateBatchResultDto result = flightDuplicateService.executeFullBatch();
        return ResponseEntity.ok(result);
    }

    /**
     * Triggers the duplicate logic for a single, caller-supplied flight
     * number.  Useful for ad-hoc reruns without executing the whole batch.
     *
     * @param request DTO containing the flight number to process
     * @return {@code 200 OK} with a {@link DuplicateResultDto} if the seed
     *         record was found; {@code 404 Not Found} otherwise
     */
    @PostMapping("/duplicate/single")
    public ResponseEntity<DuplicateResultDto> runSingle(
            @Valid @RequestBody SingleDuplicateRequestDto request) {

        DuplicateResultDto result =
                flightDuplicateService.processOneFlight(request.flightNum());

        if (result.seedFlightId() == null) {
            // Seed record was not found – return 404 with error details.
            return ResponseEntity.status(HttpStatus.NOT_FOUND).body(result);
        }
        return ResponseEntity.ok(result);
    }
}

